// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Context.sol";

/**
 * @title Business
 * @dev Gas-optimized contract for managing businesses with gasless transactions and UUID-based IDs
 */
contract Business is Context, Ownable {
    // Pack related storage variables together to optimize storage slots
    struct BusinessData {
        address owner; // 20 bytes
        bytes32 ipfsHash; // 32 bytes
        bytes16 id; // 16 bytes (UUID)
        bool isActive; // 1 byte
        uint40 updatedAt; // 5 bytes (enough for timestamps until year 2078)
    } // Total: 74 bytes (fits in 3 storage slots)

    address private _trustedForwarder;
    uint256 private _nonce; // For UUID generation

    // Storage optimizations
    mapping(bytes16 => BusinessData) private businesses;
    mapping(address => bytes16[]) private ownerBusinesses;
    mapping(address => uint96) private businessCount;

    // Events with packed parameters
    event BusinessCreated(
        bytes16 indexed businessId,
        address indexed owner,
        bytes32 ipfsHash,
        uint40 timestamp
    );
    event BusinessUpdated(
        bytes16 indexed businessId,
        bytes32 ipfsHash,
        uint40 timestamp
    );
    event BusinessStatusChanged(
        bytes16 indexed businessId,
        bool isActive,
        uint40 timestamp
    );
    event BusinessDeleted(
        bytes16 indexed businessId,
        address indexed owner,
        uint40 timestamp
    );
    event TrustedForwarderUpdated(
        address indexed oldForwarder,
        address indexed newForwarder,
        uint40 timestamp
    );

    // Custom errors
    error InvalidForwarderAddress();
    error EmptyIPFSHash();
    error BusinessNotFound(bytes16 businessId);
    error UnauthorizedAccess(address caller, bytes16 businessId);
    error InvalidBusinessData();
    error BusinessAlreadyDeleted(bytes16 businessId);
    error DuplicateUUID();

    constructor(address initialOwner) Ownable(initialOwner) {
        _nonce = uint256(
            keccak256(abi.encodePacked(block.timestamp, msg.sender))
        );
    }

    /**
     * @dev Generates a UUID using block information, sender, and nonce
     * @return uuid The generated UUID as bytes16
     */
    function _generateUUID() private returns (bytes16) {
        bytes32 hash = keccak256(
            abi.encodePacked(
                block.timestamp,
                block.prevrandao,
                msg.sender,
                _nonce++
            )
        );
        return bytes16(hash);
    }

    function getTrustedForwarder() public view returns (address) {
        return _trustedForwarder;
    }

    function setTrustedForwarder(address newForwarder) external onlyOwner {
        if (newForwarder == address(0)) revert InvalidForwarderAddress();
        address oldForwarder = _trustedForwarder;
        _trustedForwarder = newForwarder;
        emit TrustedForwarderUpdated(
            oldForwarder,
            newForwarder,
            uint40(block.timestamp)
        );
    }

    function isTrustedForwarder(address forwarder) public view returns (bool) {
        return forwarder == _trustedForwarder;
    }

    function _msgSender()
        internal
        view
        virtual
        override
        returns (address sender)
    {
        if (isTrustedForwarder(msg.sender)) {
            assembly {
                sender := shr(96, calldataload(sub(calldatasize(), 20)))
            }
            return sender;
        }
        return super._msgSender();
    }

    function _msgData()
        internal
        view
        virtual
        override
        returns (bytes calldata)
    {
        if (isTrustedForwarder(msg.sender)) {
            return msg.data[:msg.data.length - 20];
        }
        return super._msgData();
    }

    /**
     * @dev Creates a new business with IPFS hash
     * @param ipfsHash IPFS hash of business metadata
     * @return businessId The UUID of the created business
     */
    function createBusiness(
        string calldata ipfsHash
    ) external returns (bytes16) {
        if (bytes(ipfsHash).length == 0) revert EmptyIPFSHash();

        address owner = _msgSender();
        bytes16 newBusinessId = _generateUUID();

        // Ensure UUID is unique (extremely unlikely but check anyway)
        if (businesses[newBusinessId].owner != address(0))
            revert DuplicateUUID();

        // Convert string to bytes32 for storage efficiency
        bytes32 ipfsHashBytes = keccak256(bytes(ipfsHash));

        businesses[newBusinessId] = BusinessData({
            id: newBusinessId,
            owner: owner,
            ipfsHash: ipfsHashBytes,
            isActive: true,
            updatedAt: uint40(block.timestamp)
        });

        ownerBusinesses[owner].push(newBusinessId);
        unchecked {
            // Safe because one address can't create enough businesses to overflow uint96
            businessCount[owner]++;
        }

        emit BusinessCreated(
            newBusinessId,
            owner,
            ipfsHashBytes,
            uint40(block.timestamp)
        );
        return newBusinessId;
    }

    /**
     * @dev Updates business IPFS hash
     */
    function updateBusiness(
        bytes16 businessId,
        string calldata ipfsHash
    ) external {
        BusinessData storage business = businesses[businessId];
        if (business.owner == address(0)) revert BusinessNotFound(businessId);
        if (business.owner != _msgSender())
            revert UnauthorizedAccess(_msgSender(), businessId);
        if (bytes(ipfsHash).length == 0) revert EmptyIPFSHash();
        if (!business.isActive) revert BusinessAlreadyDeleted(businessId);

        bytes32 ipfsHashBytes = keccak256(bytes(ipfsHash));
        business.ipfsHash = ipfsHashBytes;
        business.updatedAt = uint40(block.timestamp);

        emit BusinessUpdated(
            businessId,
            ipfsHashBytes,
            uint40(block.timestamp)
        );
    }

    /**
     * @dev Sets business active status
     */
    function setBusinessStatus(bytes16 businessId, bool isActive) external {
        BusinessData storage business = businesses[businessId];
        if (business.owner == address(0)) revert BusinessNotFound(businessId);
        if (business.owner != _msgSender())
            revert UnauthorizedAccess(_msgSender(), businessId);

        business.isActive = isActive;
        business.updatedAt = uint40(block.timestamp);

        emit BusinessStatusChanged(
            businessId,
            isActive,
            uint40(block.timestamp)
        );
    }

    /**
     * @dev Gets business data
     */
    function getBusiness(
        bytes16 businessId
    ) external view returns (BusinessData memory) {
        BusinessData memory business = businesses[businessId];
        if (business.owner == address(0)) revert BusinessNotFound(businessId);
        return business;
    }

    /**
     * @dev Gets all business IDs owned by an address
     */
    function getBusinessesByOwner(
        address owner
    ) external view returns (bytes16[] memory) {
        return ownerBusinesses[owner];
    }

    /**
     * @dev Deletes a business and updates the owner's business count
     */
    function deleteBusiness(bytes16 businessId) external {
        BusinessData storage business = businesses[businessId];
        if (business.owner == address(0)) revert BusinessNotFound(businessId);
        if (business.owner != _msgSender())
            revert UnauthorizedAccess(_msgSender(), businessId);
        if (!business.isActive) revert BusinessAlreadyDeleted(businessId);

        address owner = business.owner;
        bytes16[] storage ownerBusinessList = ownerBusinesses[owner];
        uint256 lastIndex = ownerBusinessList.length - 1;

        // Gas-efficient array element removal
        for (uint256 i = 0; i <= lastIndex; ) {
            if (ownerBusinessList[i] == businessId) {
                if (i != lastIndex) {
                    ownerBusinessList[i] = ownerBusinessList[lastIndex];
                }
                ownerBusinessList.pop();
                break;
            }
            unchecked {
                ++i;
            }
        }

        unchecked {
            // Safe because we only decrement if there was a business
            businessCount[owner]--;
        }

        delete businesses[businessId];
        emit BusinessDeleted(businessId, owner, uint40(block.timestamp));
    }
}

contracts/Dispute.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

contract Dispute is Ownable {
    uint256 private _disputeIds;

    // Dispute status enum
    enum DisputeStatus {
        OPEN,
        IN_PROGRESS,
        RESOLVED,
        CLOSED
    }

    // Dispute reason enum
    enum DisputeReason {
        DAMAGED_ITEM,
        WRONG_ITEM,
        MISSING_ITEM,
        LATE_DELIVERY,
        QUALITY_ISSUE,
        OTHER
    }

    // Evidence type enum
    enum EvidenceType {
        IMAGE,
        VIDEO,
        CHAT_HISTORY,
        ORDER_DETAILS,
        PRODUCT_DETAILS,
        SHIPPING_DETAILS,
        PAYMENT_DETAILS,
        OTHER
    }

    // Resolution type enum
    enum ResolutionType {
        REFUND,
        REPLACEMENT,
        PARTIAL_REFUND,
        STORE_CREDIT,
        OTHER
    }

    // Evidence struct - optimized for gas
    struct Evidence {
        string pinataCid; // Using Pinata CID instead of IPFS CID
        EvidenceType evidenceType;
        uint256 timestamp;
    }

    // Resolution struct - optimized for gas
    struct Resolution {
        ResolutionType resolutionType;
        uint256 amount;
        string pinataCid; // Store resolution details on Pinata
        uint256 timestamp;
    }

    // Dispute struct - optimized for gas
    struct DisputeData {
        bytes32 id;
        bytes32 orderId;
        address buyer;
        address business;
        DisputeReason reason;
        string pinataCid; // Store dispute details on Pinata
        DisputeStatus status;
        Resolution resolution;
        uint256 evidenceCount;
        uint256 createdAt;
        uint256 updatedAt;
    }

    // Events
    event DisputeCreated(
        bytes32 indexed disputeId,
        bytes32 indexed orderId,
        address indexed buyer,
        address business,
        DisputeReason reason,
        string pinataCid
    );

    event EvidenceAdded(
        bytes32 indexed disputeId,
        string pinataCid,
        EvidenceType evidenceType
    );

    event DisputeResolved(
        bytes32 indexed disputeId,
        ResolutionType resolutionType,
        uint256 amount,
        string pinataCid
    );

    // Mapping of dispute ID to dispute data
    mapping(bytes32 => DisputeData) private disputes;

    // Mapping of dispute ID to evidence array
    mapping(bytes32 => Evidence[]) private disputeEvidence;

    // Mapping of order ID to dispute ID
    mapping(bytes32 => bytes32) private orderToDispute;

    // Mapping of user address to their disputes
    mapping(address => bytes32[]) private userDisputes;

    // Mapping of business address to their disputes
    mapping(address => bytes32[]) private businessDisputes;

    // Constructor
    constructor(address initialOwner) Ownable(initialOwner) {}

    // Create a new dispute
    function createDispute(
        bytes32 _disputeId,
        bytes32 _orderId,
        address _buyer,
        address _business,
        DisputeReason _reason,
        string memory _pinataCid
    ) external onlyOwner {
        // Check if dispute already exists for this order
        require(
            orderToDispute[_orderId] == bytes32(0),
            "Dispute already exists for this order"
        );

        // Create new dispute
        DisputeData memory newDispute = DisputeData({
            id: _disputeId,
            orderId: _orderId,
            buyer: _buyer,
            business: _business,
            reason: _reason,
            pinataCid: _pinataCid,
            status: DisputeStatus.OPEN,
            resolution: Resolution({
                resolutionType: ResolutionType.OTHER,
                amount: 0,
                pinataCid: "",
                timestamp: 0
            }),
            evidenceCount: 0,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        // Store dispute
        disputes[_disputeId] = newDispute;
        orderToDispute[_orderId] = _disputeId;
        userDisputes[_buyer].push(_disputeId);
        businessDisputes[_business].push(_disputeId);

        // Emit event
        emit DisputeCreated(
            _disputeId,
            _orderId,
            _buyer,
            _business,
            _reason,
            _pinataCid
        );
    }

    // Add evidence to dispute
    function addEvidence(
        bytes32 _disputeId,
        string memory _pinataCid,
        EvidenceType _evidenceType
    ) external onlyOwner {
        DisputeData storage dispute = disputes[_disputeId];
        require(dispute.id != bytes32(0), "Dispute not found");

        Evidence memory newEvidence = Evidence({
            pinataCid: _pinataCid,
            evidenceType: _evidenceType,
            timestamp: block.timestamp
        });

        disputeEvidence[_disputeId].push(newEvidence);
        dispute.evidenceCount++;
        dispute.updatedAt = block.timestamp;

        emit EvidenceAdded(_disputeId, _pinataCid, _evidenceType);
    }

    // Resolve dispute
    function resolveDispute(
        bytes32 _disputeId,
        ResolutionType _resolutionType,
        uint256 _amount,
        string memory _pinataCid
    ) external onlyOwner {
        DisputeData storage dispute = disputes[_disputeId];
        require(dispute.id != bytes32(0), "Dispute not found");
        require(dispute.status != DisputeStatus.CLOSED, "Dispute is closed");

        // Update dispute
        dispute.status = DisputeStatus.RESOLVED;
        dispute.resolution = Resolution({
            resolutionType: _resolutionType,
            amount: _amount,
            pinataCid: _pinataCid,
            timestamp: block.timestamp
        });
        dispute.updatedAt = block.timestamp;

        emit DisputeResolved(_disputeId, _resolutionType, _amount, _pinataCid);
    }

    // Close dispute
    function closeDispute(bytes32 _disputeId) external onlyOwner {
        DisputeData storage dispute = disputes[_disputeId];
        require(dispute.id != bytes32(0), "Dispute not found");
        require(dispute.status == DisputeStatus.RESOLVED, "Dispute must be resolved first");

        dispute.status = DisputeStatus.CLOSED;
        dispute.updatedAt = block.timestamp;
    }

    // Get dispute by ID
    function getDispute(bytes32 _disputeId)
        external
        view
        returns (DisputeData memory)
    {
        return disputes[_disputeId];
    }

    // Get dispute by order ID
    function getDisputeByOrder(bytes32 _orderId)
        external
        view
        returns (DisputeData memory)
    {
        bytes32 disputeId = orderToDispute[_orderId];
        return disputes[disputeId];
    }

    // Get user disputes
    function getUserDisputes(address _user)
        external
        view
        returns (bytes32[] memory)
    {
        return userDisputes[_user];
    }

    // Get business disputes
    function getBusinessDisputes(address _business)
        external
        view
        returns (bytes32[] memory)
    {
        return businessDisputes[_business];
    }

    // Get evidence for a dispute
    function getEvidence(bytes32 _disputeId)
        external
        view
        returns (Evidence[] memory)
    {
        return disputeEvidence[_disputeId];
    }

    // Check if dispute exists
    function disputeExists(bytes32 _disputeId) external view returns (bool) {
        return disputes[_disputeId].id != bytes32(0);
    }

    // Check if order has dispute
    function orderHasDispute(bytes32 _orderId) external view returns (bool) {
        return orderToDispute[_orderId] != bytes32(0);
    }
}

contracts/Escrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./Payment.sol";

contract GoodsEscrow {
    enum State { AWAITING_PAYMENT, AWAITING_DELIVERY, COMPLETE, REFUNDED, DISPUTE }
    State public state;

    address public immutable buyer;
    address public immutable seller;
    address public immutable arbitrator;
    uint256 public amount;
    uint256 public immutable disputeTimeLimit;
    uint256 public deliveryDeadline;
    uint256 public lastInteraction;
    bytes32 public paymentId;
    bool public isFiatPayment;

    Payment public paymentContract;

    event PaymentDeposited(address indexed buyer, uint256 amount, bool isFiat);
    event DeliveryConfirmed(address indexed buyer);
    event PaymentReleased(address indexed seller, uint256 amount);
    event RefundIssued(address indexed buyer, uint256 amount);
    event DisputeRaised(address indexed party);
    event DisputeResolved(address indexed arbitrator, address winner);

    modifier onlyBuyer() {
        require(msg.sender == buyer, "Only buyer can call this function");
        _;
    }

    modifier onlySeller() {
        require(msg.sender == seller, "Only seller can call this function");
        _;
    }

    modifier onlyArbitrator() {
        require(msg.sender == arbitrator, "Only arbitrator can call this function");
        _;
    }

    modifier inState(State expectedState) {
        require(state == expectedState, "Invalid state");
        _;
    }

    constructor(
        address _seller,
        address _arbitrator,
        uint256 _deliveryTimeframe,
        uint256 _disputeTimeLimit,
        address _paymentContract
    ) {
        buyer = msg.sender;
        seller = _seller;
        arbitrator = _arbitrator;
        disputeTimeLimit = _disputeTimeLimit;
        deliveryDeadline = block.timestamp + _deliveryTimeframe;
        lastInteraction = block.timestamp;
        state = State.AWAITING_PAYMENT;
        paymentContract = Payment(_paymentContract);
    }

    function initiatePayment(
        uint256 _amount,
        address token,
        bool _isFiat
    ) external onlyBuyer inState(State.AWAITING_PAYMENT) {
        amount = _amount;
        isFiatPayment = _isFiat;

        if (_isFiat) {
            // For fiat payments, the backend will call recordFiatPayment
            // after Paystack verification
            state = State.AWAITING_DELIVERY;
            emit PaymentDeposited(buyer, amount, true);
        } else {
            // For blockchain payments, initiate through Payment contract
            paymentId = paymentContract.initiateBlockchainPayment(
                address(this),
                amount,
                token
            );
            state = State.AWAITING_DELIVERY;
            emit PaymentDeposited(buyer, amount, false);
        }
    }

    function confirmDelivery() external onlyBuyer inState(State.AWAITING_DELIVERY) {
        require(block.timestamp <= deliveryDeadline, "Delivery confirmation period expired");

        state = State.COMPLETE;
        paymentContract.completePayment(paymentId);

        emit DeliveryConfirmed(buyer);
        emit PaymentReleased(seller, amount);
    }

    function requestRefund() external onlyBuyer inState(State.AWAITING_DELIVERY) {
        require(block.timestamp > deliveryDeadline, "Delivery period has not expired");

        state = State.REFUNDED;
        if (!isFiatPayment) {
            paymentContract.completePayment(paymentId);
        }

        emit RefundIssued(buyer, amount);
    }

    function raiseDispute() external {
        require(msg.sender == buyer || msg.sender == seller, "Only buyer or seller can raise a dispute");
        require(state == State.AWAITING_DELIVERY, "No active transaction to dispute");
        require(block.timestamp <= deliveryDeadline + disputeTimeLimit, "Dispute period expired");

        state = State.DISPUTE;
        emit DisputeRaised(msg.sender);
    }

    function resolveDispute(address winner) external onlyArbitrator inState(State.DISPUTE) {
        require(winner == buyer || winner == seller, "Winner must be buyer or seller");

        state = (winner == buyer) ? State.REFUNDED : State.COMPLETE;
        if (!isFiatPayment) {
            paymentContract.completePayment(paymentId);
        }

        emit DisputeResolved(arbitrator, winner);
        if (winner == buyer) {
            emit RefundIssued(buyer, amount);
        } else {
            emit PaymentReleased(seller, amount);
        }
    }
}

